// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IEmergencyOracle {
    function owner() external view returns (address);
}

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    // Predict CREATE address for a contract deploying with nonce 0.
    function predictCreate(address deployer) internal pure returns (address) {
        bytes memory rlp = new bytes(23);
        rlp[0] = 0xd6;
        rlp[1] = 0x94;
        assembly {
            mstore(add(rlp, 0x22), shl(96, deployer))
        }
        rlp[22] = 0x80;
        return address(uint160(uint256(keccak256(rlp))));
    }

    function testFuzz_property(address actor, string calldata description) public {
        vm.assume(actor != address(0) && actor != address(c));

        // Make the fuzzed actor an admin of c (isAdmin is slot 0 mapping).
        bytes32 slot = keccak256(abi.encode(actor, uint256(0)));
        vm.store(address(c), slot, bytes32(uint256(1)));

        vm.prank(actor);
        c.newEmergencyOracle(description);

        // Fresh state each fuzz run => c deploys the oracle with nonce 0.
        address newOracle = predictCreate(address(c));

        // Rule: the newly created emergency oracle's owner is the caller (the admin),
        // never the factory contract itself.
        assertTrue(
            newOracle.code.length > 0 && IEmergencyOracle(newOracle).owner() == actor,
            "created oracle owner must be the calling admin"
        );
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address actor, string calldata description) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));
        vm.assume(bytes(description).length < 256);

        // Drive c through the public entry point as an arbitrary caller.
        vm.prank(actor);
        try c.newEmergencyOracle(description) {
            // Success path: the newly created EmergencyOracle lives at the
            // deterministic CREATE address of C with nonce 0 (first deployment).
            address predicted = address(
                uint160(uint256(keccak256(abi.encodePacked(bytes1(0xd6), bytes1(0x94), address(c), bytes1(0x80)))))
            );

            // Read the oracle's owner() via its public surface (low-level call
            // so no re-declaration of the oracle is needed).
            (bool ok, bytes memory ret) = predicted.call(abi.encodeWithSignature("owner()"));
            address oracleOwner = ok && ret.length == 32 ? abi.decode(ret, (address)) : address(0);

            // GENERAL RULE: for every admissible caller, the factory's freshly
            // created oracle is owned by that caller, and the creation call
            // succeeds.
            assertTrue(ok && oracleOwner == actor, "oracle must be owned by the creating caller");
        } catch {
            // If creation is not permitted for this caller, the rule is that
            // ownership still cannot have been handed to the factory itself:
            // any oracle that might exist must not be owned by address(c).
            // Check via public surface whether C itself ever became an oracle
            // owner's factory — assert the revert happened before any oracle
            // could be created owned by C, i.e. predicted oracle (if it exists)
            // is not owned by address(c).
            address predicted = address(
                uint160(uint256(keccak256(abi.encodePacked(bytes1(0xd6), bytes1(0x94), address(c), bytes1(0x80)))))
            );
            (bool ok2, bytes memory ret2) = predicted.call(abi.encodeWithSignature("owner()"));
            address oracleOwner = ok2 && ret2.length == 32 ? abi.decode(ret2, (address)) : address(0);
            assertTrue(!ok2 || oracleOwner != address(c), "factory must never own the created oracle");
        }
    }
}

