pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface OracleLike {
    function owner() external view returns (address);
}

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(string calldata description) public {
        // WIDE admissible domain: any non-pathological description, the caller is
        // the test contract (the deployer/admin of c). No value is hard-coded:
        // the fuzzer supplies the description driving the creation.
        vm.assume(bytes(description).length <= 64);

        address caller = msg.sender; // the authorized caller of c.newEmergencyOracle

        // Drive the boundary through the public entry point.
        bool ok;
        try c.newEmergencyOracle(description) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: IF the call succeeded, the newly created EmergencyOracle
        // (found at one of c's recent CREATE-derived addresses) must report the
        // CALLER as its owner. The mutant makes the factory itself the owner,
        // so owner() != caller for every successful creation.
        bool rule = true;
        if (ok) {
            for (uint256 n = 1; n <= 8; n++) {
                address pred = _createAddress(address(c), n);
                uint256 cs;
                assembly {
                    cs := extcodesize(pred)
                }
                if (cs > 0) {
                    rule = rule && (OracleLike(pred).owner() == caller);
                }
            }
        }

        assertTrue(ok ? rule : true, "created oracle must be owned by the calling admin");
    }

    // Pure Solidity CREATE address derivation: keccak(rlp([sender, nonce])), small nonce (< 128).
    function _createAddress(address a, uint256 n) internal pure returns (address) {
        bytes memory rlp = abi.encodePacked(bytes1(0xd6), bytes1(0x94), a, bytes1(uint8(n)));
        bytes32 h = keccak256(rlp);
        return address(uint160(uint256(h)));
    }
}

