pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, string calldata description) public {
        vm.assume(caller != address(c));
        vm.assume(caller != address(0));

        vm.prank(caller);
        bool ok;
        try c.newEmergencyOracle(description) {
            ok = true;
        } catch {
            ok = false;
        }

        // If the factory created an oracle, it is deterministically the first
        // contract deployed by c (CREATE from address(c) with nonce 0):
        // RLP([sender, nonce]) = 0xd694 || addr || 0x80, hashed & truncated.
        address predicted = address(
            uint160(uint256(keccak256(abi.encodePacked(hex"d694", address(c), hex"80"))))
        );

        address oracleOwner = ok ? EO(predicted).owner() : address(0);

        // General rule: a successfully created EmergencyOracle is never owned
        // by the factory contract itself (P: owner == msg.sender; M: owner == c).
        assertTrue(oracleOwner != address(c));
    }
}

abstract contract EO {
    function owner() external view virtual returns (address);
}

