pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, string calldata description) public {
        // Admissible domain: any non-zero actor distinct from the factory itself.
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(bytes(description).length <= 64);

        // Grant admin rights to the fuzzed actor if the factory exposes an admin setter;
        // ignore results of these low-level calls.
        (bool g1,) = address(c).call(abi.encodeWithSignature("setAdmin(address,bool)", actor, true)); g1;
        (bool g2,) = address(c).call(abi.encodeWithSignature("setIsAdmin(address,bool)", actor, true)); g2;
        (bool g3,) = address(c).call(abi.encodeWithSignature("grantAdmin(address)", actor)); g3;
        (bool g4,) = address(c).call(abi.encodeWithSignature("addAdmin(address)", actor)); g4;

        // Deterministic address of the FIRST contract created by c (contract nonce 1):
        // keccak256(rlp([c, 1]))[12:] with rlp = d6 94 <addr20> 01.
        address predicted = address(
            uint160(uint256(keccak256(abi.encodePacked(hex"d694", uint160(address(c)), hex"01"))))
        );

        address caller = actor;
        bool ok;

        // Rule: any oracle successfully created by newEmergencyOracle is owned by its creator.
        vm.prank(actor);
        try c.newEmergencyOracle(description) {
            ok = true;
        } catch {
            // fallback: the deployer/admin path
            caller = address(this);
            try c.newEmergencyOracle(description) {
                ok = true;
            } catch {
                ok = false;
            }
        }

        assertTrue(ok && _ownerOf(predicted) == caller);
    }

    function _ownerOf(address oracle) internal view returns (address r) {
        (bool s, bytes memory d) = oracle.staticcall(abi.encodeWithSignature("owner()"));
        r = s ? abi.decode(d, (address)) : address(0);
    }
}

