pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    event NewEmergencyOracle(address owner, address newOracle);

    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address actor, string calldata description) public {
        // keep the actor in the admissible domain (wide: any non-zero, non-c address)
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));

        // grant admin rights to the fuzzed actor (isAdmin mapping lives at slot 1 of C)
        vm.store(address(c), keccak256(abi.encode(actor, uint256(1))), bytes32(uint256(1)));

        // the oracle deployed inside the call will sit at the canonical CREATE address of c with nonce 0
        address predictedOracle = address(
            uint160(uint256(keccak256(abi.encodePacked(hex"d694", address(c), hex"80"))))
        );

        // general rule: the emitted event's owner field equals msg.sender for EVERY caller
        vm.prank(actor);
        vm.expectEmit(true, true, false, true, address(c));
        emit NewEmergencyOracle(actor, predictedOracle);
        c.newEmergencyOracle(description);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(address caller, string calldata description) public {
        require(!c.isAdmin(caller), "caller must not be admin");
        (bool ok, ) = address(c).call(
            abi.encodeWithSelector(c.newEmergencyOracle.selector, description)
        );
        assert(!ok);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function testAdminCanCreateOracle(bool makeAdmin) external {
        address admin = address(0x1234);
        require(makeAdmin, "must make admin");
        c.isAdmin(admin, true);
        c.newEmergencyOracle("desc");
        assert(c.isAdmin(admin));
    }
}
